import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";
import { deployment } from "@/config/deployment";
import { getPathname } from "@/i18n/navigation";
import { openGraphLocales, routing, type AppLocale } from "@/i18n/routing";

type Href = Parameters<typeof getPathname>[0]["href"];

// The share image of each language: public/og/{locale}.png, 1200×630,
// generated by scripts/og-images.mjs from the QA page /qa/og.
export const ogImageSize = { width: 1200, height: 630 } as const;

// Everything a public page declares about itself: its canonical address and
// language versions on the production origin, the Open Graph and Twitter
// cards, and whether it may be indexed (only on the production deployment).
export async function pageMetadata({
  locale,
  href,
  title,
  description,
  type = "website",
}: {
  locale: AppLocale;
  href: Href;
  // The page's own title; the layout's template adds the name, except where
  // the title is given as { absolute }.
  title: string | { absolute: string };
  description: string;
  type?: "website" | "article";
}): Promise<Metadata> {
  const tSite = await getTranslations({ locale, namespace: "site" });
  const path = getPathname({ href, locale });
  const shareTitle = typeof title === "string" ? title : title.absolute;
  const image = {
    url: `/og/${locale}.png`,
    ...ogImageSize,
    alt: tSite("ogImageAlt"),
  };

  return {
    title,
    description,
    alternates: {
      canonical: path,
      languages: {
        ...Object.fromEntries(
          routing.locales.map((target) => [target, getPathname({ href, locale: target })]),
        ),
        "x-default": getPathname({ href, locale: routing.defaultLocale }),
      },
    },
    openGraph: {
      type,
      locale: openGraphLocales[locale],
      alternateLocale: routing.locales
        .filter((target) => target !== locale)
        .map((target) => openGraphLocales[target]),
      url: path,
      siteName: tSite("name"),
      title: shareTitle,
      description,
      images: [image],
    },
    twitter: {
      card: "summary_large_image",
      title: shareTitle,
      description,
      images: [image],
    },
    robots: deployment.indexable
      ? { index: true, follow: true }
      : { index: false, follow: false },
  };
}
